class _Path0Painter extends CustomPainter {
  const _Path0Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(32, 0);
    path.lineTo(32, 420);
    path.lineTo(24.1016, 420);
    path.lineTo(0, 420);
    path.lineTo(0, 0);
    path.close();
  }

  @override
  bool shouldRepaint(_Path0Painter oldDelegate) => false;
}

class _Path1Painter extends CustomPainter {
  const _Path1Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(8, 0);
    path.lineTo(4, 5);
    path.lineTo(0, 0);
    path.close();
  }

  @override
  bool shouldRepaint(_Path1Painter oldDelegate) => false;
}
